export type Cell = [number, number];

const SURVIVAL_NEIGHBOUR_COUNTS = [2, 3];

const isNeighbour = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1 && !(x === otherX && y === otherY);

const countLiveNeighbours = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((other) => isNeighbour(cell, other)).length;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) =>
    SURVIVAL_NEIGHBOUR_COUNTS.includes(countLiveNeighbours(cell, liveCells)),
  );
}

